INSERT INTO public.kb_nodes VALUES ('190d6cc1-da0e-55e8-b41b-0dbe5273d630', '63ad19a3-66dd-5d6a-b1e0-45114c1b5af7', NULL, 'section', 'Перечень терминов и сокращений', NULL, NULL, 'Перечень терминов и сокращений', '| \*\*Термин / Сокращение\*\* | \*\*Определение\*\*                                                                                                                                                                                                   |
