INSERT INTO public.kb_nodes VALUES ('4152730d-4f02-5deb-bfaf-83677b6d2d30', '9535f0ad-ca45-5553-b95b-9a0b9c12699b', '7d3a158d-7c06-5360-b2c8-508b90e1d6d3', 'article', 'Общая информация > 6.4.1 Данные о документе', NULL, NULL, '6.4.1 Данные о документе', 'Во время заполнения полей на странице редактирования можно сохранить введенные данные по кнопке «Сохранить» (2 - Рисунок 36) и закрыть страницу редактирования. Далее, если открыть страницу просмотра Исполнения – будут отображены данные c учетом изменений на странице редактирования. Для возврата на страницу редактирования необходимо нажать кнопку «Продолжить выполнение операции» в области кнопок действия (Рисунок 37)

