INSERT INTO public.kb_nodes VALUES ('7df6ee6c-2ce6-51e1-ad9c-d0f1256de379', '461c92d0-3769-5f54-afad-b8e839fd02a0', '0071e4b0-1321-53bf-a593-ee24e7b7add3', 'article', 'Содержание > 1.1.2 Требование к YML-файлу', NULL, NULL, '1.1.2 Требование к YML-файлу', '- В YML нельзя использовать непечатаемые символы с ASCII-кодами<sup>4</sup> от 0 до 31 (за исключением символов с кодами 9, 10, 13 — табуляция, перевод строки, возврат каретки);
- Символы " & > < '' нужно заменять на эквивалентные коды(**Таблица 1**):

