INSERT INTO public.kb_nodes VALUES ('cd57c62f-6d03-5a86-9abe-3200ad2a1c21', '6e7cc5b8-0435-5d78-b20d-d88612dea69e', '913584cd-9a6e-537d-a189-f963fd94f430', 'article', 'СОДЕРЖАНИЕ > 2.5.1 **Поля ввода: текстовое и числовое**', NULL, NULL, '2.5.1 **Поля ввода: текстовое и числовое**', 'Поле ввода (Рисунок 1) используется для ввода текстовой и числовой информации:
