INSERT INTO public.kb_nodes VALUES ('9fa77a07-6707-5233-8801-28c63c6d6066', '6e7cc5b8-0435-5d78-b20d-d88612dea69e', 'e249620a-da04-5df5-9634-e80cc3e6a131', 'article', 'Владимир Ефимов: В Москве подвели итоги первых аукционов за право размещения плоскостных парковок > 3.3.5.2 Добавление пользователей к организации вручную', NULL, NULL, '3.3.5.2 Добавление пользователей к организации вручную', 'Для добавления пользователей к организации вручную необходимо перейти в личный кабинет, нажав кнопку **«Управление профилем»** во всплывающем пользовательском меню (Рисунок 106) и в открывшемся личном кабинете нажать кнопку **«Профиль компании»**.

