INSERT INTO public.kb_nodes VALUES ('f900804c-bb44-5708-a24a-08be6e6dc574', '6e7cc5b8-0435-5d78-b20d-d88612dea69e', 'fff4ad86-3dd0-555e-bce3-c57faefe7c99', 'article', '7 Школа поставщика > 2 Доработка заявки, повторная подача', NULL, NULL, '2 Доработка заявки, повторная подача', 'В заявке в статусе «Требуется доработка» в верхней части заявки отображается сообщение от оператора (Рисунок 176 (1)). В нижней части заявки отображается кнопка «Доработать заявку» (Рисунок 176 (2)), которую необходимо нажать для перехода к доработке заявки.

> Заявку в статусе «Отклонена» также можно доработать и направить повторно.

Рисунок 176 – Заявка на банковскую гарантию, кнопка «Доработать заявку»

