INSERT INTO public.kb_nodes VALUES ('90d6cad5-756e-5579-b7c2-8798d49e745d', '6e7cc5b8-0435-5d78-b20d-d88612dea69e', 'c29c0ed8-d084-5cf0-9296-90d4700a60f8', 'article', '10 Избранное > 10.2 Избранные ТРУ', NULL, NULL, '10.2 Избранные ТРУ', 'В разделе «Избранное ТРУ» отображаются товары, работы, услуги, сохраненные в избранное пользователем. Добавление СТЕ в избранное доступно авторизованным пользователям.

Для добавления СТЕ в избранное следует нажать на пиктограмму в виде звездочки на карточке СТЕ в Каталоге ТРУ (Рисунок 264 (1)) или на странице СТЕ (Рисунок 265 (1)).

