INSERT INTO public.kb_nodes VALUES ('8f041569-a9ca-5fca-bdad-2f10167651a9', '6e7cc5b8-0435-5d78-b20d-d88612dea69e', 'c29c0ed8-d084-5cf0-9296-90d4700a60f8', 'article', '10 Избранное > 11.5.8 Формирование УПД', NULL, NULL, '11.5.8 Формирование УПД', 'На странице документа УПД доступны элементы интерфейса для предварительного скачивания файлов УПД (**Рисунок 356 – Предварительное скачивание файлов УПД**). Эти же элементы отображаются на странице исправительного УПД (**Рисунок 357 – Предварительное скачивание файлов исправительного УПД**).

Предварительное скачивание файлов УПД

