INSERT INTO public.kb_nodes VALUES ('ddfbffe4-bb30-52bc-8b3c-d8d8f474a308', '6e7cc5b8-0435-5d78-b20d-d88612dea69e', 'c29c0ed8-d084-5cf0-9296-90d4700a60f8', 'article', '10 Избранное > 12.1.1 Заявка на изменение сведений о компании', NULL, NULL, '12.1.1 Заявка на изменение сведений о компании', 'Для изменения сведений о компании необходимо в разделе «Управление профилем» всплывающего пользовательского меню нажать на кнопку «Профиль компании».

