INSERT INTO public.kb_nodes VALUES ('0297cbc0-38eb-5ce8-9d5f-cce155d83951', '6e7cc5b8-0435-5d78-b20d-d88612dea69e', 'c29c0ed8-d084-5cf0-9296-90d4700a60f8', 'article', '10 Избранное > 12.2.5 Создание филиала или подразделения', NULL, NULL, '12.2.5 Создание филиала или подразделения', 'Если филиал или подразделение ещё не зарегистрирован на Портале поставщиков у администратора компании головной организации есть возможность направить приглашение на регистрацию представителю филиала. Для этого необходимо в реестре «Филиалы и подразделения» (раздел 12.2.1) нажать на кнопку «Действия над филиалом», затем выбрать действие «Создать филиал или подразделение».

