INSERT INTO public.kb_nodes VALUES ('7ad3fdf2-8074-5e72-8a6c-6df8b3f0fb1f', '6e7cc5b8-0435-5d78-b20d-d88612dea69e', '5c1d0d00-706a-5e7a-aae1-e69867b5bae5', 'article', 'Заблокированные участники КС > 26.3 Дополнительные сервисы', NULL, NULL, '26.3 Дополнительные сервисы', 'Необходимо в шапке портала нажать кнопку **«Оставить обращение»** (Рисунок 593). По умолчанию открывается модальное окно с формой обращения в службу технической поддержки (Рисунок 595). Необходимо перейти на вкладку «Дополнительные сервисы» (Рисунок 598):

