INSERT INTO public.kb_nodes VALUES ('787f7b99-5a15-5d7f-914b-ead20b18b039', '5ec28370-8961-54c9-bc4a-1bcd20b6d3a3', '412f71d0-b5e4-5292-9ee3-4caf737358d1', 'article', 'Регистрация пользователя > 4.1.5. Добавление МЧД', NULL, NULL, '4.1.5. Добавление МЧД', 'Машиночитаемая доверенность (далее МЧД) - цифровой аналог бумажной доверенности на подписание документов в электронном виде. МЧД необходима сотруднику ЮЛ или ИП, подписывающего документ ЭП физического лица. Лицо, имеющее право без доверенности действовать от имени юридического лица, должно иметь ЭП юридического лица.

На Портале поставщиков существует два способа добавления доверенности в профиль пользователя:

* Профиль пользователя: «Операции с МЧД» - пользователь сам добавляет xml-файл доверенности к профилю пользователя, полученный и подписанный ЭП руководителя организации;
* Профиль компании: «Операции с МЧД» - у администратора есть возможность добавлять xml-файл доверенности к профилю пользователя сотрудников своей организации.', NULL, 305, '2026-09-12 20:32:48.687381+03', DEFAULT, DEFAULT, DEFAULT, DEFAULT);
INSERT INTO public.kb_nodes VALUES ('31f20774-d6ee-5341-8284-690e1ba7258c', '5ec28370-8961-54c9-bc4a-1bcd20b6d3a3', '412f71d0-b5e4-5292-9ee3-4caf737358d1', 'article', 'Регистрация пользователя > 4.1.5.1. Профиль пользователя «Операции с МЧД»', NULL, NULL, '4.1.5.1. Профиль пользователя «Операции с МЧД»', 'Для добавления МЧД пользователю необходимо нажать на кнопку «Операции с МЧД» (Рисунок 113 (5)) после чего откроется страница «Машиночитаемые доверенности пользователя» (Рисунок 121).

