INSERT INTO public.kb_nodes VALUES ('f8387b9a-ce98-5973-9f96-e2a4df36a2d8', '5ec28370-8961-54c9-bc4a-1bcd20b6d3a3', '1b04f92a-5092-56b1-91b3-69d54544caf1', 'article', '8. Осуществление закупки > 8.1.2. Сервис коммуникации между поставщиком и заказчиком', NULL, NULL, '8.1.2. Сервис коммуникации между поставщиком и заказчиком', 'После отправки заявки поставщику у заказчика есть возможность инициировать чат по кнопке «Начать обсуждение» (Рисунок 203).

