INSERT INTO public.kb_nodes VALUES ('2cfd40a0-cecb-5e0b-b0a3-72dfabb2fb70', '9535f0ad-ca45-5553-b95b-9a0b9c12699b', '3089426d-f50b-58b7-87e3-e986f1037640', 'item', 'Спецификация > 6.5 Подписание документа > 6.5.2 Подписание документа и отправка в Диадок', NULL, NULL, '6.5.2 Подписание документа и отправка в Диадок', 'После нажатия кнопки «Сгенерировать УПД» необходимо обновить страницу. В результате успешной генерации в блоке «Электронные документы, сформированные системой» появится документ с типом «Xml файл УПД по формату ФНС» и префиксом «ON_NSCHFDOPPR_».

После появления Xml-документа нажмите «Подписать и отправить», ознакомьтесь со сформированным Xml-документом, выберите ЭЦП, нажмите «Подписать и отправить». Статус исполнения изменится на «Отправка УПД оператору ЭДО».

