INSERT INTO public.kb_nodes VALUES ('9dd9791d-7c88-5cbc-ace2-dd10dead8f31', '5ec28370-8961-54c9-bc4a-1bcd20b6d3a3', 'b7986d9c-8cfd-551c-bace-c58b861d2f80', 'item', 'Содержание > 2.4.**Условные обозначения действий и элементов интерфейса** > 2.4.6. Радиокнопка', NULL, NULL, '2.4.6. Радиокнопка', '*Радиокнопка или переключатель позволяет пользователю выбрать одну опцию (пункт) из предопределенного набора (группы) (Рисунок 7).*

