INSERT INTO public.kb_nodes VALUES ('93b5586a-fe1a-536a-93e5-8028e4c151a2', '6e7cc5b8-0435-5d78-b20d-d88612dea69e', '783d6770-491d-5d1d-b753-7dc5061bc139', 'item', '10 Избранное > 11.5.7 Заполнение Спецификации > 11.5.7.7 Заполнение RFID-метки и гарантийного срока для товаров МАФ', NULL, NULL, '11.5.7.7 Заполнение RFID-метки и гарантийного срока для товаров МАФ', 'При наличии в спецификации товаров МАФ у пользователя появляется возможность добавить RFID-метку и гарантийный срок в месяцах по каждой позиции товара МАФ. Для этого необходимо нажать кнопку «Выгрузить xlsx», в полученном файле заполнить столбцы «Идентификатор метки» и «Гарантийный срок, мес», сохранить файл и нажатием кнопки «Загрузить xls с данными о МАФ» выбрать на устройстве пользователя заполненный файл и загрузить его на Портал поставщиков. Файл после загрузки обрабатывается Порталом автоматически и при отсутствии ошибок в заполнении данные загружаются на форму УПД.

