INSERT INTO public.kb_nodes VALUES ('75dbf92f-71bd-55c4-91a9-82b7d0ff6e18', '6e7cc5b8-0435-5d78-b20d-d88612dea69e', '280491df-d05b-51c2-a26f-8ea8fb1feabe', 'item', '14 Обращения > 14.2.2 Просмотр жалобы о необоснованной блокировке > 14.2.5 Получение решения арбитражной комиссии по жалобе', NULL, NULL, '14.2.5 Получение решения арбитражной комиссии по жалобе', 'После того, как арбитражная комиссия вынесет решение по жалобе о необоснованной блокировке поставщика, обращение примет статус «**Решение арбитражной комиссии**», а также на странице жалобы отобразится решение и заключение арбитражной комиссии (Рисунок 451).

