INSERT INTO public.kb_nodes VALUES ('61b2ec9e-a437-5e8d-89f6-4c664cc64ac6', '5ec28370-8961-54c9-bc4a-1bcd20b6d3a3', 'a6836410-4928-5307-b3b8-cbe45114c95a', 'item', 'Машиночитаемые доверенности пользователя > 6.3.Плановый бюджет особых закупок > 6.3.1. Действия, доступные заказчику в разделе «Плановый бюджет особых закупок»', NULL, NULL, '6.3.1. Действия, доступные заказчику в разделе «Плановый бюджет особых закупок»', 'В разделе «Плановый бюджет особых закупок» заказчику доступны следующие функции:

− **Обновить из ЕИС**. При нажатии на кнопку «Обновить из ЕИС» запускается импорт план-графика из ЕИС. Функция «Обновить из ЕИС» доступна не чаще одного раза в час.
− Внесение корректировок лимитов бюджета. При нажатии на иконку icon: edit в столбце «Корректировка» реализована возможность указать суммарную стоимость контрактов, заключенных вне Портала поставщиков (Рисунок 178).

Плановый бюджет особых закупок

**Рисунок 178 – Внесение корректировок лимитов бюджета**', NULL, 254, '2026-09-12 20:32:48.747178+03', DEFAULT, DEFAULT, DEFAULT, DEFAULT);
