INSERT INTO public.kb_nodes VALUES ('02236c97-8a45-5da2-afd2-321b991217c4', '5ec28370-8961-54c9-bc4a-1bcd20b6d3a3', '34801f69-5717-50ad-b930-dd51e59d86df', 'item', 'СОЗДАНИЕ КОТИРОВОЧНОЙ СЕССИИ > 9.3. Работа с контрактом в интерфейсе 2 > 9.3.2.1. Выбор из участников потребности', NULL, NULL, '9.3.2.1. Выбор из участников потребности', 'В проекте контракта в статусе «Ввод сведений», сформированном из закупки по потребностям в блоке «Сведения о поставщике» отображается кнопка для изменения выбранного предложения «Выбрать из участников потребности» (Рисунок 296).

