INSERT INTO public.kb_nodes VALUES ('122f5968-794c-52b2-aeb9-c09f330a7545', '9535f0ad-ca45-5553-b95b-9a0b9c12699b', '8757b72e-f28a-5430-9df8-627ea91a2732', 'item', '7 Доступные действия Поставщика и схемы процессов > 8.15 Заполнение сведений о маркировке товара > 8.15.1 Общие пояснения > 8.15.1.1 Как проверяется корректность заполнения', NULL, NULL, '8.15.1.1 Как проверяется корректность заполнения', 'Сведения о маркировке заполняются по необходимости и не обязательны для заполнения.

Указанные сведения не проходят проверку:

---

83

* при отправке из ПП в оператора ЭДО,
* при обработке документа на стороне оператора ЭДО

При выявлении ошибок в сведениях о маркировке в подписанном УПД необходимо:

* при ГИС ЕИС, выступающим в роли оператора ЭДО - Поставщику сделать исправление для УПД;
* при операторе ЭДО Калуга-Астрал - Заказчику направить УПД на аннулирование и Поставщику сформировать новый УПД;
* при операторе ЭДО Диадок - Заказчику направить УПД на доработку с помощью Уведомления об уточнении и Поставщику сформировать новый УПД.', NULL, 272, '2026-09-12 20:32:48.759463+03', DEFAULT, DEFAULT, DEFAULT, DEFAULT);
