INSERT INTO public.kb_chunks VALUES ('9b8ee64a-774c-515f-ad96-d4172514665b', '7bc808ac-74b7-5300-92c2-f61b424797f1', 'Заключив контракт, исполнение по которому будет происходить в электронном виде через Портал поставщиков, поставщик сразу может подготовиться к успешному исполнению, не дожидаясь дня отгрузки.

