INSERT INTO public.kb_chunks VALUES ('83f98f55-d62c-5ce7-9af0-8db7db1d63be', 'efeb7119-5f5f-5968-a7be-3e89971a9d7e', '**Рисунок 40 – Страница редактирования Спецификация исполнения контракта**

