INSERT INTO public.kb_chunks VALUES ('a8471f0c-58ae-5711-a0f5-4d9da9fdadd1', 'a0c330d8-6e68-5c21-8728-ddbaf4404b11', 'При работе со спецификацией Исполнения по контрактам по лекарственным средствам доступно множественное указание одной позиции спецификации контракта с помощью кнопок:

