INSERT INTO public.kb_chunks VALUES ('88e24e39-30b9-5e99-8401-99c20ba3764a', 'ba76e0e4-2d79-5395-bf61-bc0014a54938', 'Довести до конца процесса с помощью интерфейса ЕИС, т.е. без использования ПП - один из двух вариантов:

