INSERT INTO public.kb_chunks VALUES ('77aa9827-da0d-52e0-a1a8-eeda1b71cb93', 'f2a880ed-94b9-50d4-8580-4dfb7d5968bc', '**Рисунок 63 – Отображение сообщения «Уполномоченные подписанты не**
