INSERT INTO public.kb_chunks VALUES ('ace04e15-2cd9-53a5-99f7-2b40d214e90f', '2d97def2-59f5-5abf-93cf-b403f85fd4e8', 'По строительным контрактам существует 2 варианты исполнения: необходимость исполняться с указанием накопительным итогом и без.

