INSERT INTO public.kb_chunks VALUES ('c8626b5c-7af1-5b23-979e-1c102f747ac1', 'd39a379d-e81f-5434-939e-1876782b64b5', 'Машиночитаемая доверенность (далее МЧД) - цифровой аналог бумажной доверенности на подписание документов в электронном виде.

На Портале поставщиков существует два способа добавления доверенности в профиль пользователя:

* Профиль пользователя: «Операции с МЧД» - пользователь сам добавляет xml-файл доверенности к профилю пользователя, полученный и подписанный ЭП руководителя организации;
* Профиль компании: «Операции с МЧД» - у администратора есть возможность добавлять xml-файл доверенности к профилю пользователя сотрудников своей организации.', NULL, '[]', 'bge-m3', '2026-09-12 20:32:48.869591+03');
