INSERT INTO public.kb_chunks VALUES ('edc2b3e3-3e3f-5e91-aaf2-455cc83a0a19', 'd18906d6-cd34-53af-844b-cca1d6dbb2ac', '**Таблица 2 – ПО АРМ пользователей Системы**

