INSERT INTO public.kb_chunks VALUES ('df19425d-ee41-57a8-9239-3e873b1c2fef', '46fc75d9-5375-5be8-a53f-1636db5be724', 'На Портале поставщиков возможны следующие способы регистрации (Рисунок 38):
