INSERT INTO public.kb_chunks VALUES ('2839ad16-8c8b-53bc-88b5-2db867749b5c', 'b1cd1a44-f843-52a0-a9bc-d5354654a348', 'Для входа на Портал необходимо нажать на кнопку «Войти», расположенную в верхней части главной страницы Портала (Рисунок 28):

