INSERT INTO public.kb_chunks VALUES ('b829ea9e-3e08-551f-a81d-49088aa7d7b8', '4ad8b78c-3f24-515f-9269-78a221e113da', '**Рисунок 127 – Меню личного кабинета пользователя поставщика**

Меню личного кабинета пользователя включает в себя следующие разделы:
