INSERT INTO public.kb_chunks VALUES ('b113c232-12d2-5d96-9d19-c2bbc5c3039f', '8fdf9d1f-76ec-5735-856c-0ca6618547ca', 'После подписания и отправки документов в ЕЭТП статус заявки изменится на «На рассмотрении», и пользователь сможет ознакомиться с ответами банков:
