INSERT INTO public.kb_chunks VALUES ('0d91bd58-cef2-5a70-93bd-450b2b5bec4d', '7e3a989d-96ca-50dd-826e-29c29f8f5130', '**Рисунок 192 – Страница ответа от банка, действия пользователя**

