INSERT INTO public.kb_chunks VALUES ('d2bf2a6d-2165-5db7-a87e-bf0ce9f60171', '75d4070b-ba70-53ef-a4f3-c4066a776f87', '**Рисунок 221 – Страница раздела «Каталог продукции», неактивная кнопка массового подписания оферт**

