INSERT INTO public.kb_chunks VALUES ('33e65668-1a26-526c-acb3-a003450cef2f', 'cccbc4bb-91a9-5ba5-86c5-be7eea1cfde5', 'На карточке избранной закупки пользователю доступны следующие действия:

