INSERT INTO public.kb_chunks VALUES ('994f7a22-6762-547a-a865-0cff59679520', '21d08b2b-f4d7-5632-80f7-cdc7f4198e89', 'В зависимости от вида контракта используется один из двух видов интерфейсов пользователя, которые отличаются по url адресу и по внешнему виду:

1) https://old.zakupki.mos.ru/#/contracts/my/[id контракта] (Рисунок 271):
    * контракты, данные по которым ПП получает из Региональной информационной системы Заказчика;
    * контракты от московских Заказчиков с признаком Электронного исполнения;
    * контракты от московских Заказчиков без признака Электронного исполнения;
    * контракты, которые зарегистрированы по кнопке "Зарегистрировать контракт" после заключения не электронным способом;', NULL, '[]', 'bge-m3', '2026-09-12 20:32:48.875411+03');
