INSERT INTO public.kb_chunks VALUES ('7858300f-f99c-5612-8f65-3a578e0a1716', '3db7ef6d-6f1f-5db9-a1d3-749b7f77ecda', '! Сроки на совершение действий Поставщиком – 48 часов.

