INSERT INTO public.kb_chunks VALUES ('50735387-f076-5444-aa6b-a4802a26bfbb', 'fdf2fbea-bf80-5b85-920a-e6694bf55297', 'Сведения на вкладке «Протокол разногласий» на странице контракта

