INSERT INTO public.kb_chunks VALUES ('9c169639-0c60-5b96-b052-abd9c21fd2b3', '4fdfe428-832c-57a7-b932-43bfc7e75932', 'Карточка найденного исполнения содержит следующую информацию (Рисунок 307):

