INSERT INTO public.kb_chunks VALUES ('ae076df4-bd9e-593c-97c2-55669677ea7a', '46801a3b-ff93-5a3f-af6a-a6d3d7badb33', 'Сортировкой по умолчанию в реестре исполнений является сортировка по дате создания исполнения. В начале списка отображаются новые исполнения, в конце списка – старые. Дополнительно пользователю доступны сортировки по следующим критериям (Рисунок 310):

* Дата исполнения;
* Номер исполнения;

