INSERT INTO public.kb_chunks VALUES ('ae280a0d-3808-5415-99fa-41aa730a2caa', 'f758fd6e-e6fa-5a68-9173-fa5c6d8bf9ed', 'Параметр заполнения в текстовом формате должен быть выбран при следующих условиях:
