INSERT INTO public.kb_chunks VALUES ('d17154a3-8dc3-5be2-9b78-8b25cfb7b586', 'f758fd6e-e6fa-5a68-9173-fa5c6d8bf9ed', 'Как узнать, что есть необходимость указания сведений о прослеживаемости:

