INSERT INTO public.kb_chunks VALUES ('08f90303-926a-5613-ab64-f8de6d91b3b9', 'ddfbffe4-bb30-52bc-8b3c-d8d8f474a308', 'Для изменения сведений о компании необходимо в разделе «Управление профилем» всплывающего пользовательского меню нажать на кнопку «Профиль компании».

