INSERT INTO public.kb_chunks VALUES ('9985a6bf-5814-5e5e-a68e-71b46cb72ac0', 'ddfbffe4-bb30-52bc-8b3c-d8d8f474a308', '**Рисунок 379 – Кнопка «Отправить заявку»**

После подтверждения заявки модераторами внесенные сведения о компании будут изменены.
