INSERT INTO public.kb_chunks VALUES ('1bef82b0-2f73-52d4-bc42-e5afad9de75d', 'ab1b3c47-178b-5a93-bf3a-07fe7d5694a1', 'Если поставщик был заблокирован, он может подать жалобу за необоснованную блокировку на Портале.

