INSERT INTO public.kb_chunks VALUES ('62c19575-ebeb-5777-ad82-f0b6af31ad32', '31848120-9315-5a1c-8704-98539767a38a', 'Открытая часть Портала поставщиков предназначена (Рисунок 473):
