INSERT INTO public.kb_chunks VALUES ('b1465b09-7edb-59e0-9bc1-dbb67b1c1855', 'f041ab53-805c-5509-98e6-427813cbdcb9', '**Закупка по потребностям** – процедура сбора коммерческих предложений в форме ставок участников с целью заключения контракта (договора) с любым из них. Закупка по потребностям проводится путем подачи ставок участником, ставки принимаются до истечения срока, установленного Заказчиком. До истечения срока действия закупки по потребности участник может редактировать ставку, или же отозвать её. Заказчик может отменить закупку по потребности, находящуюся в статусе «Прием предложений» до завершения срока подачи заявок.

Общая схема процесса взаимодействия Поставщика и Заказчика на рисунке ниже (Рисунок 540).', NULL, '[]', 'bge-m3', '2026-09-12 20:32:48.882579+03');
