INSERT INTO public.kb_chunks VALUES ('33a436b6-8d07-5ee2-a61c-818afc6163d7', '7d7eb4dc-c23b-5ed3-b4ea-2a8e79561518', 'При нажатии на наименование закупки в едином реестре закупок (раздел 19) откроется страница закупки, которая содержит следующую информацию (Рисунок 555):

