INSERT INTO public.kb_chunks VALUES ('b4f6576a-71e9-5716-887b-c75e13ef1865', '2e2ac4c1-2711-5aa0-a5c1-9ee98ac2704f', 'Для перехода к разделу «Связь с внешними системами и соглашения» необходимо из панели управления пользователя, нажать на раздел «Управление пользователем» и выбрать раздел «Связь с внешними системами и соглашения» (Рисунок 130).
