INSERT INTO public.kb_chunks VALUES ('348368c0-7fef-5907-90e4-e84614b87180', 'c7e69fb2-0b62-5b75-a7b1-c681fdd97abc', '**Рисунок 192 – Модальное окно «Корзина»**

