INSERT INTO public.kb_chunks VALUES ('6c93d198-8cdb-56a1-bae3-2270fdfcfb6f', '910948f0-347d-5f20-b99d-98faf53f5cef', '**Рисунок 207 – Публикация котировочной сессии через раздел меню «Мои котировочные сессии»**

