INSERT INTO public.kb_chunks VALUES ('df630c75-8905-59b9-9906-fcc5d4e4777f', '5b78be49-4700-57d6-a82e-b8fe3c23d741', 'После нажатия кнопки «Заключить» для выбранного предложения в столбце «Действия» отображается ссылка «Перейти к контракту».

