INSERT INTO public.kb_chunks VALUES ('3388bce1-2816-578e-95ad-539460c234c5', '02fa9fee-82bd-592c-abe4-f13a0d194de1', 'Страница редактирования текущей версии контракта состоит из:
* области отображения статусной модели контракта (Рисунок 293 (1)). На текущем активном статусе дополнительно отображается перечень блоков текущей формы.

При клике на один из элементов, страница будет перемещена к этому элементу (Рисунок 292 (2));
* области отображения данных о контракте (Рисунок 293 (3)) – часть полей редактируется;
* области для расположения кнопок действия (Рисунок 293 (4)) – стандартно отображаются 3 кнопки:
    * «Сохранить» (Рисунок 294 (1)) – сохраняет введенные данные и приложенные файлы на странице редактирования;
    * «Отменить операцию» (Рисунок 294 (2)) – удаляет введенные данные и приложенные файлы на странице редактирования, удаляет страницу редактирования, возвращает возможность использовать кнопки по доступным действиям на странице просмотра в области «Доступные действия» (Рисунок 292 (1));
    * кнопка завершения действия (Рисунок 294 (3)), выбранного на странице просмотра, и перевода контракта на следующий статус.', NULL, '[]', 'bge-m3', '2026-09-12 20:32:48.918626+03');
