INSERT INTO public.kb_chunks VALUES ('c27540bf-4b09-5d6d-8020-ba63adeda4ae', '9f9a5aee-8d0c-5fe6-a32f-b5253c28d7ce', 'После отправки файла поставщику заказчику будет доступно действие по замене отправленного дополнительного соглашения.

