INSERT INTO public.kb_chunks VALUES ('759667b8-19ef-5848-9dee-951697ff66b8', '6dcc48b9-e0ac-507c-95cf-eb182bdf3d2d', 'После отправки файла поставщику заказчику будет доступно действие по отказу от текущей версии дополнительного соглашения, которое было отправлено на подпись поставщику.

