INSERT INTO public.kb_chunks VALUES ('b8956289-1295-5be6-8419-7738be3d5eb8', '6612e0ad-6d54-5b3e-847a-186311368a07', 'Просмотреть все закупки Портала поставщиков можно с помощью единого реестра закупок - в **меню Портала поставщиков** (Рисунок 28) нажать на «**Единый реестр закупок**».

