INSERT INTO public.kb_chunks VALUES ('f8a12cbc-80e7-5589-b10f-f940164415f2', '9a70be20-8ac3-5467-bad3-527528ae2deb', 'В едином реестре можно сохранить часто используемый набор фильтров, для этого необходимо:

