INSERT INTO public.kb_chunks VALUES ('82ad57b5-2478-5279-845a-9d21fb7f6d17', '3f584a60-cf9f-5866-ae97-99b315147326', 'Рисунок 29 – Блок добавления поставки для ценового предложения

