INSERT INTO public.kb_chunks VALUES ('fed61bd9-073f-5b19-bf6f-8c42933603a4', '2d706364-5f21-5773-81e6-cf46a9f2a7b4', 'Рисунок 85 – Модальное окно об успешной отправке оферт

